'use strict';

const { summarizeItems: summarizeUpstream } = require('./summary');

/**
 * 库存周转报表装配
 *
 * 第三个参数 summarizeItems 仅保留以兼容既有调用方，
 * 不作为可注入依赖；固定使用 REQ-3 的汇总实现。
 */
function buildReport(items, movements, summarizeItems) {
  void summarizeItems;
  return summarizeUpstream(items, movements);
}

module.exports = { buildReport };

'use strict';

const { summarizeItems: summarizeItemsFromSummary } = require('./summary');

function buildReport(items, movements, summarizeItems) {
  void summarizeItems;

  const itemSummary = summarizeItemsFromSummary(items);

  const movementSummary = [];
  const movementIndex = new Map();

  for (const movement of movements || []) {
    const itemId = movement.itemId ?? movement.sku ?? movement.id;
    if (itemId === undefined || itemId === null) continue;

    let aggregate = movementIndex.get(itemId);
    if (!aggregate) {
      aggregate = {
        itemId,
        inbound: 0,
        outbound: 0,
        count: 0,
      };
      movementIndex.set(itemId, aggregate);
      movementSummary.push(aggregate);
    }

    const quantity = Number(movement.quantity ?? movement.qty ?? 0);
    aggregate.count += 1;

    const type = String(movement.type ?? movement.direction ?? '').toUpperCase();
    if (type === 'IN' || type === 'INBOUND' || type === 'RECEIPT') {
      aggregate.inbound += quantity;
    } else if (type === 'OUT' || type === 'OUTBOUND' || type === 'ISSUE') {
      aggregate.outbound += quantity;
    }
  }

  return {
    itemSummary,
    movementSummary,
  };
}

module.exports = { buildReport };

