'use strict';

const { summarizeItems } = require('./summary');

/**
 * REQ-12 库存周转报表
 * 报表装配：调用 REQ-3 提供的 summarizeItems 生成物项汇总，并计算周转指标。
 */
function buildReport(items = [], movements = []) {
  const summary = summarizeItems(items, movements);
  const rows = normalizeSummary(summary);

  return rows.map((row) => {
    const item = items.find((candidate) => candidate.id === row.itemId || candidate.id === row.id) || {};
    const totalOut = Number(row.totalOut ?? row.outQty ?? row.out ?? 0);
    const averageInventory = Number(
      item.averageInventory ?? item.avgInventory ?? row.currentStock ?? row.endingStock ?? 0
    );
    const turnover = averageInventory > 0 ? totalOut / averageInventory : 0;

    return {
      ...row,
      itemId: row.itemId ?? row.id,
      turnover,
      turnoverDays: turnover > 0 ? 365 / turnover : 0,
    };
  });
}

function normalizeSummary(summary) {
  if (Array.isArray(summary)) return summary;
  if (summary && typeof summary === 'object') {
    return Object.keys(summary).map((key) => ({ itemId: key, ...summary[key] }));
  }
  return [];
}

module.exports = { buildReport };

'use strict';

const summary = require('./summary');

/**
 * Build an inventory-turnover report.
 *
 * The report assembly service REQ-12 depends on REQ-3's pure summarizer.
 * The third argument is kept for backward-compatible call signatures only;
 * REQ-12 must always call the upstream REQ-3 export instead of an injected
 * bypass implementation.
 */
function buildReport(items, movements, summarizeItems) {
  void summarizeItems; // signature compatibility; upstream call used below
  const summaryResult = summary.summarizeItems(items);
  return { summary: summaryResult, movements };
}

module.exports = { buildReport };

